mapper.codeEditorJavascript:
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const titles=arr(input.sheets).map(s=>String(((s||{}).properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
for(const off of [0,-1]){ const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+off,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(titles.includes(t)) tabs.push(t); }
const q=s=>"'"+s+"'";
const f=[{a1Range:"'יעדים'!A2:U200"}];
if(titles.includes('ניתוקים')) f.push({a1Range:"'ניתוקים'!A1:M5000"});
tabs.forEach(t=>f.push({a1Range:q(t)+'!A1:Z1500'}));
return {tabs:JSON.stringify(tabs), readBody:JSON.stringify({dataFilters:f, valueRenderOption:'FORMATTED_VALUE'})};

const norm=s=>String(s==null?'':s).replace(/\s+/g,' ').trim();
const digits=s=>String(s==null?'':s).replace(/\D/g,'');
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const vals=x=>((x&&x.valueRange)||x||{}).values||[];
const ALIAS={'אוסי':'אוסי גיאן','אופק פ':'אופק','דוד':'דוד חי','איתמר':'איתמר ששון'};
const d1=arr(input.d1).map(v=>(v&&v.valueRange)||v||{});
const byName=n=>{ const x=d1.find(v=>{ const r=norm(v.range).replace(/^'/,''); return r.startsWith(n+"'!")||r.startsWith(n+'!'); }); return (x&&x.values)||[]; };
const tabs=arr(input.tabs).map(norm);
const targets=byName('יעדים'), dtab=byName('ניתוקים');
const ph=digits(input.phone); const p9=ph.slice(-9);
const outPhone=ph.startsWith('972')?ph:('972'+ph.replace(/^0+/,''));
const pad=n=>('0'+n).slice(-2);
const now=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const todayTxt=pad(now.getDate())+'/'+pad(now.getMonth()+1)+'/'+now.getFullYear();
const todayDM=pad(now.getDate())+'/'+pad(now.getMonth()+1);
const res=(ack,wr)=>({ok:!!(wr&&wr.length), ack, outPhone, writeBody:JSON.stringify({valueInputOption:'RAW',data:wr||[]}), writeCount:(wr||[]).length});
const names=targets.map(r=>norm((r||[])[0])).filter(Boolean);
const resolve=c=>{ c=norm(c); if(ALIAS[c]) c=ALIAS[c]; if(!c) return ''; if(names.includes(c)) return c;
  const cand=names.filter(n=>n.split(' ')[0]===c||c.split(' ')[0]===n); return cand.length===1?cand[0]:''; };
let rep='';
targets.forEach(r=>{ if(!r) return; const n=norm(r[0]); if(n && p9.length===9 && digits(r[1]).slice(-9)===p9) rep=n; });
if(!rep) return res('לא מצאתי אותך ברשימת הנציגים. תדבר עם סטיב.');
const raw=String(input.text==null?'':input.text).trim();
// RULE (Steve 10/11/2026): an answer without the word ביטול/ניתוק ("1 ...", "2 ...") is matched to what is open for the rep (cancellations or disconnects); the number may be followed by just a space. Do not remove.
const dk=s=>{ const m=norm(s).match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{4}))?/); return m?((+(m[3]||now.getFullYear()))*10000+(+m[2])*100+(+m[1])):0; };
const getItems=cancel=>{ const items={}; let maxD=0; const mine=[];
  if(!cancel){
    dtab.forEach((r,i)=>{ if(!r) return; if(digits(r[1]).length<6) return; if(norm(r[4])!==rep) return; const d=dk(r[8]); const n=Number(norm(r[12]))||0; if(!d||!n) return; mine.push({i,r,d,n}); if(d>maxD) maxD=d; });
    mine.filter(x=>x.d===maxD).forEach(x=>{ items[x.n]={kind:'d', row:x.i+1, name:norm(x.r[2]), ans:String(x.r[10]==null?'':x.r[10])}; });
  } else {
    tabs.forEach(tb=>{ const rows=byName(tb); const hE=(rows[0]||[]).map(norm).findIndex(x=>x.startsWith('הסבר נציג')); if(hE<0) return;
      rows.forEach((r,i)=>{ if(i===0||!r) return; const ev=norm(r[hE]); const mk=ev.match(/^⏳\D*(\d{1,2}\/\d{1,2})\s*#(\d+)/); if(!mk) return;
        if(resolve(r[7])!==rep) return; const d=dk(mk[1]); mine.push({tb,hE,i,name:norm(r[2]),d,n:+mk[2]}); if(d>maxD) maxD=d; }); });
    mine.filter(x=>x.d===maxD).forEach(x=>{ items[x.n]={kind:'c', tb:x.tb, col:x.hE, row:x.i+1, name:x.name}; });
  }
  return items; };
const hasKW=/^\s*(ניתוקים?|ביטולים?|נפילה)/.test(raw);
let isCancel=/^\s*(ביטול|ביטולים|נפילה)/.test(raw);
let items;
if(hasKW) items=getItems(isCancel);
else { const ci=getItems(true), di=getItems(false);
  const cn=Object.keys(ci).length, dn=Object.keys(di).filter(k=>!di[k].ans).length;
  if(cn&&!dn){ isCancel=true; items=ci; }
  else if(dn&&!cn){ isCancel=false; items=di; }
  else if(cn&&dn) return res('יש לך גם ביטולים וגם ניתוקים שמחכים לתשובה. תכתבו לפני כל תשובה את המילה, למשל:\nביטול 1 - ...\nניתוק 1 - ...');
  else return res('אין לך כרגע ביטול או ניתוק שמחכה להסבר 👍'); }
const KW=isCancel?'ביטול':'ניתוק';
const t=raw.replace(/^\s*(ניתוקים?|ביטולים?|נפילה)\s*[:\-–]?\s*/,'').trim();
const nums=Object.keys(items).map(Number).sort((a,b)=>a-b);
if(!nums.length) return res(isCancel?'אין לך כרגע ביטול שמחכה להסבר 👍':'אין לך כרגע ניתוק פתוח שמחכה לתשובה 👍');
if(t.length<2) return res('חסר פירוט. תכתבו ככה: '+KW+' 1 - '+(isCancel?'מה קרה ולמה הלקוח ביטל':'מה קרה, שימרתם או לא, ולמה הוא התנתק'));
const re=new RegExp('(?:^|\\n)\\s*(?:'+KW+'\\s*)?(\\d{1,2})(\\s*[-–.):]\\s*|\\s+)','g'); const ms=[]; let m;
while((m=re.exec(t))!==null){ const n=+m[1]; if(!/[-–.):]/.test(m[2])&&!items[n]) continue; ms.push({n,s:m.index,e:re.lastIndex}); }
const segs={};
if(ms.length){ ms.forEach((x,i)=>{ const end=i+1<ms.length?ms[i+1].s:t.length; const s=t.slice(x.e,end).trim(); if(s) segs[x.n]=s; }); }
else if(nums.length===1){ segs[nums[0]]=t; }
else return res('יש לך '+nums.length+' '+(isCancel?'ביטולים':'ניתוקים')+' בהודעה, צריך מספר לפני כל תשובה. למשל:\n'+KW+' 1 - ...\n'+KW+' 2 - ...');
const classify=s=>{ if(/לא\s*(שומר|שימר|שימרתי|שימרנו|הצלחתי|הצלחנו|נשאר|רוצה להישאר)|נותק|ניתק|מתנתק|עזב|עוזב|עבר ל/.test(s)) return 'לא שומר';
  if(/שומר|שימרתי|שימרנו|נשאר|ביטל[הו]?\s*(את\s*)?ה?ניתוק/.test(s)) return 'שומר'; return 'לא ברור'; };
const colL=n=>{ let s=''; n++; while(n>0){ const k=(n-1)%26; s=String.fromCharCode(65+k)+s; n=Math.floor((n-1)/26); } return s; };
const wr=[]; const okL=[], missL=[], badN=[];
Object.keys(segs).map(Number).forEach(n=>{ if(!items[n]) badN.push(n); });
nums.forEach(n=>{ const it=items[n]; const s=segs[n];
  if(!s){ if(!(it.kind==='d'&&it.ans)) missL.push(n+'. '+it.name); return; }
  const text=s.slice(0,500);
  if(it.kind==='d'){ const full=it.ans?(it.ans.includes(text)?it.ans:it.ans+' | '+text):text;
    wr.push({range:"'ניתוקים'!J"+it.row+":L"+it.row, values:[[classify(full), full, todayTxt]]}); }
  else wr.push({range:"'"+it.tb+"'!"+colL(it.col)+it.row, values:[[text+' (נציג '+todayDM+')']]});
  okL.push(it.name); });
const lines=[];
if(okL.length) lines.push((isCancel?'רשמתי את ההסבר בדוח המכר: ':'רשמתי בחוצץ הניתוקים: ')+okL.join(', ')+' 👍');
if(badN.length) lines.push('מספר '+badN.join(', ')+' לא מופיע בהודעה ששלחתי לך.');
if(missL.length) lines.push('עוד חסרה תשובה על:\n'+missL.join('\n')+'\nתכתבו: '+KW+' <מספר> - '+(isCancel?'מה קרה ולמה הלקוח ביטל':'מה קרה, שימרתם או לא, ולמה הוא התנתק'));
return res(lines.join('\n')||'לא הבנתי. תכתבו ככה: '+KW+' 1 - ...',wr);
